    if (!match) {
      throw new Error('Invalid duration part');
    }
    const value = parseFloat(match[1]);
    switch (match[2].toLowerCase()) {
      case 'd':
        seconds += value * 86400;
        break;
      case 'h':
        seconds += value * 3600;
        break;
      case 'm':
        seconds += value * 60;
        break;
      case 's':
        seconds += value;
        break;
      default:
        throw new Error('Unknown unit');
    }
  }
  return seconds;
}
