      const char = line[i];
      if (char === '"') {
        if (!inQuote) {
          inQuote = true;
        } else {
          inQuote = false;
          if (currentField && currentField[currentField.length - 1] === '"') {
            currentField = currentField.slice(0, -1);
          }
        }
      } else if (char === ',' && !inQuote) {
        currentRow.push(currentField);
        currentField = '';
      } else if (char === '\r' && i + 1 < line.length && line[i + 1] === '\n') {
        currentRow.push(currentField);
        currentField = '';
        break;
      } else {
        currentField += char;
      }
      i++;
    }
    if (inQuote) {
      throw new Error('Unclosed quote');
    }
    if (currentField) {
      currentRow.push(currentField);
    }
    if (currentRow.length > 0 || line.trim() !== '') {
      rows.push(currentRow);
      currentRow = [];
    }
  }
  if (currentRow.length > 0) {
    rows.push(currentRow);
  }
  return rows;
