export function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError('Input must be an array');
  }
  const validIntervals = intervals.filter(([start, end]) => {
    if (!Array.isArray([start, end]) || start > end || !Number.isInteger(start) || !Number.isInteger(end)) {
      return false;
    }
    return true;
  });
  if (validIntervals.length === 0) {
    return [];
  }
  validIntervals.sort((a, b) => a[0] - b[0]);
  const merged = [validIntervals[0]];
  for (let i = 1; i < validIntervals.length; i++) {
    const current = validIntervals[i];
    const last = merged[merged.length - 1];
    if (current[0] <= last[1]) {
      last[1] = Math.max(last[1], current[1]);
    } else {
      merged.push(current);
    }
  }
  return merged;
}
